// ts-proto generated message.ts/rendezvous.ts probe `globalThis.Buffer` at
// runtime. @types/node is intentionally excluded from tsconfig (types:
// ["vite/client"]) because fresh 2026 resolutions of @types/node@26 are not
// parseable by the pinned TypeScript 4.x; declare the optional Node Buffer
// global ambiently so the generated code type-checks.
declare var Buffer: any;
